/*************************************************************************/
/** Function Name:  GetCharIndex_UFT8                                 **/
/** Purpose:        Get character index in font library.                **/
/** Resources:      None.                                               **/
/** Params:                                                             **/
/** @ uiCode[in]:   Character code.                                     **/
/** Return:         Character index.                                    **/
/*************************************************************************/
SGUI_INT GetCharIndex_UFT8(SGUI_UINT32 uiCode)
{
    /*----------------------------------*/
    /* Variable Declaration             */
    /*----------------------------------*/
    SGUI_INT iIndex;
    const SGUI_CHAR *pcChar;
    SGUI_UINT32 uiCharacterCode;
    int count;

    /*----------------------------------*/
    /* Initialize                       */
    /*----------------------------------*/
    // Initialize variable.
    iIndex = 95; // ？ 没有的字库用？表示
    count = 0;

    /*----------------------------------*/
    /* Process                          */
    /*----------------------------------*/
    /* for ASCII characters. */
    if ((uiCode > 0x19) && (uiCode < 0x7F))
    {
        iIndex = uiCode - (0x20);
    }
    else
    {
        pcChar = ChineseList;
        while (((NULL != pcChar) && ('\0' != *pcChar)))
        {
            uiCharacterCode = 0;
            pcChar = StepNext_UFT8(pcChar, &uiCharacterCode);
            if (uiCode == uiCharacterCode)
            {
                iIndex = 95 + (count * 2);
                break;
            }
            count++;
        }
    }
    return iIndex;
}

/*************************************************************************/
/** Function Name:  StepNext_UFT8                                     **/
/** Purpose:        Read current character code order by input pointer  **/
/**                 and step to next character start pointer.           **/
/** Resources:      None.                                               **/
/** Params:                                                             **/
/** @ cszSrc[in]:   Current char pointer.                               **/
/** @ puiCode[in]:  Character code.                                     **/
/** Return:         Next character start pointer.                       **/
/*************************************************************************/
SGUI_CSZSTR StepNext_UFT8(SGUI_CSZSTR cszHeader, SGUI_UINT32 *puiUnicode)
{
    /*----------------------------------*/
    /* Variable Declaration				*/
    /*----------------------------------*/
    uint16_t uiUTF8Length = 0;
    uint8_t uiUTF8HeadByte = (uint8_t)(*cszHeader);
    uint32_t uft8_code = 0;

    /*----------------------------------*/
    /* Process							*/
    /*----------------------------------*/
    if ((uiUTF8HeadByte > 0x00) && (uiUTF8HeadByte <= 0x7F)) // 单字节
    {
        uiUTF8Length = 1;
        uft8_code = (*cszHeader);
    }
    else if (0xC0 == (uiUTF8HeadByte & 0xE0)) // 双字节
    {
        uiUTF8Length = 2;
        uft8_code = ((*cszHeader) << 8) | (*(cszHeader + 1));
    }
    else if (0xE0 == (uiUTF8HeadByte & 0xF0)) // 三字节
    {
        uiUTF8Length = 3;
        uft8_code = (((*cszHeader) << 16) | ((*(cszHeader + 1)) << 8) | (*(cszHeader + 2)));
    }
    else if (0xF0 == (uiUTF8HeadByte & 0xF8)) // 四字节
    {
        uiUTF8Length = 4;
        uft8_code = (((*cszHeader) << 24) | ((*(cszHeader + 1)) << 16) | ((*(cszHeader + 1)) << 8) | (*(cszHeader + 2)));
    }
    else
    {
        uiUTF8Length = 0;
    }
    cszHeader += uiUTF8Length;
    *puiUnicode = uft8_code;
    return cszHeader;
}

/*************************************************************************/
/** Function Name:  UFT8_GetFontData                                  **/
/** Purpose:        Read character data form font data.                 **/
/** Resources:      None.                                               **/
/** Params:                                                             **/
/** @ sStartAddr[in]: Read start address in memory.                     **/
/** @ pDataBuffer[in]: Character data dump buffer pointer.              **/
/** @ sReadSize[in]: Size of data will be read, always mean the buffer  **/
/**                 size.                                               **/
/** Return:         Data in process was be read.                        **/
/*************************************************************************/
SGUI_SIZE UFT8_GetFontData(SGUI_SIZE sStartAddr, SGUI_BYTE *pDataBuffer, SGUI_SIZE sReadSize)
{
    /*----------------------------------*/
    /* Variable Declaration             */
    /*----------------------------------*/
    SGUI_SIZE sReadCount;
    const SGUI_BYTE *pSrc = UFT8_H12 + sStartAddr;
    SGUI_BYTE *pDest = pDataBuffer;

    /*----------------------------------*/
    /* Initialize                       */
    /*----------------------------------*/
    pSrc = UFT8_H12 + sStartAddr;
    pDest = pDataBuffer;

    /*----------------------------------*/
    /* Process                          */
    /*----------------------------------*/
    if (NULL != pDataBuffer)
    {
        for (sReadCount = 0; sReadCount < sReadSize; sReadCount++)
        {
            *pDest++ = *pSrc++;
        }
    }
    return sReadCount;
}

/*************************************************************************/
/** Function Name:  UFT8_GetFontData                                  **/
/** Purpose:        Read character data form font data.                 **/
/** Resources:      None.                                               **/
/** Params:                                                             **/
/** @ sStartAddr[in]: Read start address in memory.                     **/
/** @ pDataBuffer[in]: Character data dump buffer pointer.              **/
/** @ sReadSize[in]: Size of data will be read, always mean the buffer  **/
/**                 size.                                               **/
/** Return:         Data in process was be read.                        **/
/*************************************************************************/
SGUI_BOOL UFT8_IsFullWidth(SGUI_UINT32 uiCode)
{
    /*----------------------------------*/
    /* Variable Declaration             */
    /*----------------------------------*/
    SGUI_BOOL bReturn;

    /*----------------------------------*/
    /* Process                          */
    /*----------------------------------*/
    if (uiCode < 0x7F)
    {
        bReturn = SGUI_FALSE;
    }
    else
    {
        bReturn = SGUI_TRUE;
    }

    return bReturn;
}
